// STRUCT-0040: a display label for any connector provider name -- avoids a
// hardcoded aleph/opensanctions name map that would need a new branch for
// every future connector (firecrawl, or anything else CONNECTOR_SPECS gains).
const providerLabel=(p:string):string=>p.length?p.charAt(0).toUpperCase()+p.slice(1):p;

