// Relationship graph (issue #39 wiring): renders the reusable vis-network
// <EntityGraph>. Same inputs, node set and click behaviour as the previous
// hand-drawn SVG: nodes are the loaded entities that appear as an endpoint of
// a shown relationship; clicking a node opens its dossier, clicking an edge
// opens the existing relationship detail panel. No evidence status is passed,
// so every node/edge uses the component's neutral "unknown" styling -- the
// graph does not infer evidentiary status.
function Graph({relationships,entities,onNode,onEdge}:{relationships:Relationship[],entities:CanonicalEntity[],onNode:(id:string)=>void,onEdge:(r:Relationship)=>void}): ReactElement{
 const ids=Array.from(new Set(relationships.flatMap(r=>[r.source.id,r.target.id]))); const nodes=ids.map(id=>entities.find(e=>e.id===id)).filter(Boolean) as CanonicalEntity[]; if(!nodes.length)return <div className="muted">No relationships match the current filter.</div>;
 const known=new Set(nodes.map(n=>n.id)); const shown=relationships.filter(r=>known.has(r.source.id)&&known.has(r.target.id));
 return <EntityGraph height={420} nodes={nodes.map(n=>({id:n.id,label:n.caption,schema:n.schema,title:`${n.caption} · ${n.schema}`}))} edges={shown.map(r=>({id:r.id,from:r.source.id,to:r.target.id,label:r.schema,title:`${r.source.caption} → ${r.target.caption} · ${r.schema}`}))} onNodeClick={onNode} onEdgeClick={id=>{const edge=shown.find(r=>r.id===id);if(edge)onEdge(edge)}}/>
}

// The selected investigation is shared state (lib/workbench-store.ts) and
// lives in the address bar as ?inv=, so a reload or a shared link opens the
// same case (Foundation Fixes fix 3). window.history, not the Next router:
// it changes only the address, without a navigation.
function rememberInvestigation(id:string):void{
  useWorkbenchStore.getState().setInvestigationId(id);
  if(typeof window==='undefined')return;
  const url=new URL(window.location.href);
  if(id)url.searchParams.set('inv',id);else url.searchParams.delete('inv');
  if(url.href!==window.location.href)window.history.replaceState(window.history.state,'',url.href);
}

function investigationToOpen(rows:Investigation[]):string{
  const wanted=typeof window==='undefined'?null:new URLSearchParams(window.location.search).get('inv');
  return (rows.find(r=>r.id===wanted)||rows[0])?.id||'';
}

