 const stageRelationshipFromExtraction=async()=>{const c=relationshipClaimCandidate;if(!c?.accepted_record_id||!extractionRelSource||!extractionRelTarget)return;if(extractionRelSource===extractionRelTarget){setDocStatus('Relationship endpoints must be different canonical entities.');return}try{const row=await api.object(`/api/claims/${c.accepted_record_id}/relationship-proposals`,'relationship extraction proposal',isExtractionCandidate,{method:'POST',body:{schema:extractionRelSchema,source_entity_id:extractionRelSource,target_entity_id:extractionRelTarget,note:'Reporter staged from reviewed document claim in Next.js workbench'}});setDocCandidates(cur=>[...cur,row]);setRelationshipClaimCandidate(null);setExtractionRelSource('');setExtractionRelTarget('');setDocStatus('Relationship staged as a proposal. It is not canonical until separately accepted.')}catch(error){setDocStatus(errorMessage(error,'Could not stage relationship proposal'))}};
