 const openClaim=async(claim:Claim)=>{claimReviewController.current?.abort();const controller=new AbortController();claimReviewController.current=controller;claimReviewTarget.current=claim.id;const investigationId=inv;setSelectedClaim(claim);setClaimStatus(claim.status);setClaimConfidence(claim.confidence);setClaimEvidence([]);setClaimWorkspace(null);setClaimReviewStatus('Loading claim review workspace…');try{const workspace=await api.unknown(`/api/claims/${claim.id}/review-workspace`,{signal:controller.signal}) as ClaimReviewWorkspace;if(!controller.signal.aborted&&claimReviewTarget.current===claim.id&&activeInvestigation.current===investigationId){setClaimEvidence(workspace.evidence||[]);setClaimWorkspace(workspace);setClaimReviewStatus('')}}catch(error){if(!isAbortError(error)){setClaimReviewStatus('');reportPayloadError(error)}}};
